            value = c == 3 ? alpha : alpha > half(0.0f) ? (left * la + right * ra) / alpha : half(0.0f);
        }

        if (op == 14 && c == 4)
            value = Luminance(src, sw, sh, x, y, p[5]);
        return c == 3 ? ClampHalf(value) : value;
    }

    float Hue(float p, float q, float t)
    {
        if (t < 0.0f)
            t += 1.0f;
        if (t > 1.0f)
            t -= 1.0f;
        return t < 1.0f / 6.0f ? p + (q - p) * 6.0f * t : t < 0.5f ? q : t < 2.0f / 3.0f ? p + (q - p) * (2.0f / 3.0f - t) * 6.0f : p;
    }

    float Adjust(float rr, float gg, float bb, int c, device const float* p)
    {
        float maxV = p[5], bf = p[15] - 1.0f;
        float r = bf >= 0.0f ? rr + (maxV - rr) * bf : rr * (1.0f + bf);
        float g = bf >= 0.0f ? gg + (maxV - gg) * bf : gg * (1.0f + bf);
        float b = bf >= 0.0f ? bb + (maxV - bb) * bf : bb * (1.0f + bf);
        r = ((r / maxV - 0.5f) * p[16] + 0.5f) * maxV;
        g = ((g / maxV - 0.5f) * p[16] + 0.5f) * maxV;
        b = ((b / maxV - 0.5f) * p[16] + 0.5f) * maxV;
        if (abs(p[17] - 1.0f) > 1e-6f)
        {
            float gray = 0.2126f * r + 0.7152f * g + 0.0722f * b;
            r = gray + p[17] * (r - gray);
            g = gray + p[17] * (g - gray);
            b = gray + p[17] * (b - gray);
        }

        if (abs(p[18]) > 1e-6f)
        {
            float nr = r / maxV, ng = g / maxV, nb = b / maxV;
            float hi = FMax(nr, FMax(ng, nb)), lo = FMin(nr, FMin(ng, nb));
            float delta = hi - lo, h = 0.0f;
            if (delta > 1e-6f)
            {
                if (hi == nr)
                {
                    float t = (ng - nb) / delta;
                    h = 60.0f * (t - 6.0f * float(int(t / 6.0f)));
                }
                else if (hi == ng)
                    h = 60.0f * ((nb - nr) / delta + 2.0f);
                else
                    h = 60.0f * ((nr - ng) / delta + 4.0f);
                if (h < 0.0f)
                    h += 360.0f;
            }

            float l = (hi + lo) * 0.5f;
            float s = l > 0.0f && l < 1.0f ? delta / (1.0f - abs(2.0f * l - 1.0f)) : 0.0f;
            h += p[18];
            if (h < 0.0f)
                h += 360.0f;
            if (h >= 360.0f)
                h -= 360.0f;
            if (s < 1e-6f)
            {
                r = l * maxV;
                g = r;
                b = r;
            }
            else
            {
                float q = l < 0.5f ? l * (1.0f + s) : l + s - l * s, t = 2.0f * l - q;
                r = Hue(t, q, h / 360.0f + 1.0f / 3.0f) * maxV;
                g = Hue(t, q, h / 360.0f) * maxV;
                b = Hue(t, q, h / 360.0f - 1.0f / 3.0f) * maxV;
            }
        }

        if (abs(p[19] - 1.0f) > 1e-6f)
        {
            r = maxV * pow(r / maxV, 1.0f / p[19]);
            g = maxV * pow(g / maxV, 1.0f / p[19]);
            b = maxV * pow(b / maxV, 1.0f / p[19]);
        }

        if (abs(p[20]) > 1e-6f)
        {
            float gray = 0.2126f * r + 0.7152f * g + 0.0722f * b, sat = 1.0f + p[20] * 0.5f;
            r = gray + sat * (r - gray);
            g = gray + sat * (g - gray);
            b = gray + sat * (b - gray);
        }

        r *= 1.0f + p[21] * 0.01f;
        b *= 1.0f - p[21] * 0.01f;
        if (p[22] > 0.5f)
        {
            r = maxV - r;
            g = maxV - g;
            b = maxV - b;
        }

        if (p[23] > 1e-6f)
        {
            float lum = 0.2126f * r + 0.7152f * g + 0.0722f * b, gs = p[23] >= 1.0f ? 1.0f : 1.0f - p[23];
            r = lum + gs * (r - lum);
            g = lum + gs * (g - lum);
            b = lum + gs * (b - lum);
        }

        return c == 0 ? r : c == 1 ? g : b;
    }

    kernel void resident_compute(device const ResidentKernelPixel* src [[buffer(0)]], device const ResidentKernelPixel* second [[buffer(1)]], device const float* p [[buffer(2)]], device ResidentKernelPixel* dst [[buffer(3)]], uint index [[thread_position_in_grid]])
    {
        int i = int(index);
        int op = int(p[0]), sw = int(p[1]), sh = int(p[2]), w = int(p[3]), h = int(p[4]);
        int threads = op == 5 ? h * (p[14] > 0.0f ? 5 : 4) : op == 6 ? w * (p[14] > 0.0f ? 5 : 4) : w * h;
        if (i >= threads) return;
        int channels = p[14] > 0.0f ? 5 : 4;
        float maxOut = p[6];
        int tw = int(p[7]), th = int(p[8]);
        if (op == 5 || op == 6)
        {
            int lines = op == 5 ? h : w, c = i / lines, line = i % lines;
            int length = op == 5 ? w : h, step = op == 5 ? 1 : w, start = op == 5 ? line * w : line;
            int radius = int(p[15]), count = 0;
            if (c >= 3)
            {
                half sum = half(0.0f), weight = half(1.0f / (2.0f * float(radius) + 1.0f));
                for (int k = 0; k <= radius && k < length; k++)
                {
                    sum += ReadHalf(src, start + k * step, c) * weight;
                    count++;
                }

                for (int j = 0; j < length; j++)
                {
                    StoreHalf(dst, start + j * step, c, c == 4 ? ReadHalf(src, start + j * step, c) : ClampHalf(sum / half(float(count) / (2.0f * float(radius) + 1.0f))));
                    if (channels == 4)
                        StoreHalf(dst, start + j * step, 4, half(1.0f));
                    if (j - radius >= 0)
                    {
                        sum -= ReadHalf(src, start + (j - radius) * step, c) * weight;
                        count--;
                    }

                    if (j + radius + 1 < length)
                    {
                        sum += ReadHalf(src, start + (j + radius + 1) * step, c) * weight;
                        count++;
                    }
                }

                return;
            }

            float total = 0.0f;
            for (int k = 0; k <= radius && k < length; k++)
            {
                total += Read(src, start + k * step, c);
                count++;
            }

            for (int j = 0; j < length; j++)
            {
                float value = total / float(count);
                Store(dst, start + j * step, c, Clamp(value, 0.0f, maxOut));
                if (j - radius >= 0)
                {
                    total -= Read(src, start + (j - radius) * step, c);
                    count--;
                }

                if (j + radius + 1 < length)
                {
                    total += Read(src, start + (j + radius + 1) * step, c);
                    count++;
                }
            }

            return;
        }

        int x = i % w, y = i / w;
        float fx = float(x), fy = float(y), fw = float(w), fh = float(h), fsw = float(sw), fsh = float(sh), sx = fx, sy = fy;
        if (op == 1)
